CREATE TABLE work_catalog(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,name TEXT NOT NULL,kind TEXT NOT NULL,target TEXT NOT NULL,owner_id TEXT NOT NULL,requires_manager INTEGER NOT NULL DEFAULT 0,capacity INTEGER,revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE work_fulfilments(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,work_id TEXT NOT NULL,catalog_id TEXT NOT NULL,beneficiary_id TEXT NOT NULL,purpose TEXT NOT NULL,expires_at TEXT,revision INTEGER NOT NULL DEFAULT 1,UNIQUE(workspace_id,work_id,catalog_id));
CREATE TABLE work_delegations(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,manager_id TEXT NOT NULL,delegate_id TEXT NOT NULL,starts_at TEXT NOT NULL,expires_at TEXT NOT NULL,revoked_at TEXT);
CREATE TABLE work_calendars(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,name TEXT NOT NULL,timezone TEXT NOT NULL,weekdays_json TEXT NOT NULL,start_hour INTEGER NOT NULL,end_hour INTEGER NOT NULL,holidays_json TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE work_commitments(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,work_id TEXT NOT NULL,calendar_id TEXT NOT NULL,calendar_revision INTEGER NOT NULL,response_minutes INTEGER NOT NULL,resolution_minutes INTEGER NOT NULL,response_due_at TEXT NOT NULL,resolution_due_at TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,UNIQUE(workspace_id,work_id));
